// @scaleflex/dam-core — canonical auth service.
//
// The single source of truth for Filerobot auth across the widgets. Accepts the canonical
// (`container`) shape AND asset-picker's drifted (`projectToken`) shape, normalizing the
// latter. See plan/05 + plan/11 (F1).
import type {
  AnyAuthConfig,
  AssetPickerAuth,
  AuthConfig,
  AuthHeaders,
  ResolvedAuth,
} from './auth.types';

interface SassKeyResponse {
  status: 'success' | 'error';
  key: string;
  msg?: string;
}

const DEFAULT_API_HOST = 'https://api.filerobot.com';

const EXCHANGE_TIMEOUT_MS = 30_000;
const DEFAULT_EXCHANGE_RETRIES = 2;
const DEFAULT_EXCHANGE_RETRY_DELAY_MS = 400;

/**
 * Whether an exchange HTTP status is worth retrying. The Filerobot key endpoint
 * can return a transient **404** (as well as 408/429/5xx) for a perfectly valid
 * security template — e.g. an edge/cache miss — so a valid config intermittently
 * fails the exchange. Retrying these a few times absorbs the blip.
 */
function isTransientStatus(status: number): boolean {
  return status === 404 || status === 408 || status === 429 || status >= 500;
}

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/**
 * Container base URL, e.g. "https://api.filerobot.com/akli".
 * `apiDomain` overrides the default host. The REST client appends `/v5` to this
 * for the Files/Folders API.
 */
export function getApiBase(container: string, apiDomain?: string): string {
  const host = (apiDomain || DEFAULT_API_HOST).replace(/\/+$/, '');
  return `${host}/${container}`;
}

/**
 * Exchange a security template id for a short-lived SASS key.
 *
 * Resilience: the response is fetched with `cache: 'no-store'` (the key is
 * short-lived and security-sensitive — never serve a cached key or a cached
 * transient 404), and transient failures (404/408/429/5xx, network errors) are
 * retried a few times with linear backoff. This fixes the intermittent
 * "SASS key exchange failed (HTTP 404)" seen with a valid container + template.
 */
export async function exchangeSassKey(
  container: string,
  securityTemplateId: string,
  apiDomain?: string,
  opts: { retries?: number; retryDelayMs?: number } = {},
): Promise<string> {
  const url = `${getApiBase(container, apiDomain)}/key/${encodeURIComponent(securityTemplateId)}`;
  const retries = opts.retries ?? DEFAULT_EXCHANGE_RETRIES;
  const retryDelayMs = opts.retryDelayMs ?? DEFAULT_EXCHANGE_RETRY_DELAY_MS;

  let lastError: Error = new Error('SASS key exchange failed');

  for (let attempt = 0; attempt <= retries; attempt++) {
    if (attempt > 0) await sleep(retryDelayMs * attempt);

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), EXCHANGE_TIMEOUT_MS);

    try {
      const response = await fetch(url, { signal: controller.signal, cache: 'no-store' });
      clearTimeout(timeoutId);

      if (!response.ok) {
        lastError = new Error(`SASS key exchange failed (HTTP ${response.status})`);
        if (isTransientStatus(response.status) && attempt < retries) continue;
        throw lastError;
      }

      const data: SassKeyResponse = await response.json();
      if (data.status === 'error') {
        // A definitive backend rejection (bad/expired template) — don't retry.
        throw new Error(`SASS key exchange failed: ${data.msg || 'Unknown error'}`);
      }
      return data.key;
    } catch (err) {
      clearTimeout(timeoutId);
      if (err instanceof DOMException && err.name === 'AbortError') {
        throw new Error('SASS key exchange timed out');
      }
      // Network-level failures (fetch rejects with a TypeError) are transient.
      if (err instanceof TypeError && attempt < retries) {
        lastError = err;
        continue;
      }
      throw err;
    }
  }

  throw lastError;
}

/** Build auth headers from a (possibly resolved) SASS key. */
export function buildAuthHeaders(auth: AuthConfig, resolvedSassKey?: string): AuthHeaders {
  const headers: AuthHeaders = {};

  switch (auth.mode) {
    case 'security-template':
      if (!resolvedSassKey) {
        throw new Error(
          '[dam-core] Cannot build auth headers for security-template mode: SASS key ' +
            'exchange has not been performed. Call resolveAuth() first, or use sass-key mode.',
        );
      }
      headers['X-Filerobot-Key'] = resolvedSassKey;
      break;
    case 'sass-key':
      headers['X-Filerobot-Key'] = auth.sassKey;
      break;
  }

  if (auth.airboxPuid) {
    headers['X-Filerobot-Airbox-Puid'] = auth.airboxPuid;
  }
  return headers;
}

/** Narrow an unknown auth config to the asset-picker (drifted) shape. */
function isAssetPickerAuth(auth: AnyAuthConfig): auth is AssetPickerAuth {
  return auth.mode === 'securityTemplate' || auth.mode === 'sassKey';
}

/**
 * Normalize any accepted auth shape onto the canonical {@link AuthConfig}. The canonical
 * shape passes through untouched; asset-picker's `projectToken`/camelCase shape is mapped.
 */
export function normalizeAuth(auth: AnyAuthConfig): AuthConfig {
  if (!isAssetPickerAuth(auth)) return auth;

  if (auth.mode === 'securityTemplate') {
    return {
      mode: 'security-template',
      container: auth.projectToken,
      securityTemplateId: auth.securityTemplateKey,
      airboxPuid: auth.airboxPuid,
    };
  }
  return {
    mode: 'sass-key',
    container: auth.projectToken,
    sassKey: auth.sassKey,
    airboxPuid: auth.airboxPuid,
  };
}

/**
 * Resolve any accepted auth shape into a ready-to-use base URL + headers.
 * Accepts the canonical {@link AuthConfig} or asset-picker's {@link AssetPickerAuth}.
 * For security-template mode this performs the SASS key exchange.
 */
export async function resolveAuth(auth: AnyAuthConfig, apiDomain?: string): Promise<ResolvedAuth> {
  const cfg = normalizeAuth(auth);
  const apiBase = getApiBase(cfg.container, apiDomain);

  if (cfg.mode === 'security-template') {
    const sassKey = await exchangeSassKey(cfg.container, cfg.securityTemplateId, apiDomain);
    return { apiBase, headers: buildAuthHeaders(cfg, sassKey), sassKey };
  }
  return { apiBase, headers: buildAuthHeaders(cfg) };
}
