// FUTURE @scaleflex/dam-core — labels service. See ../README.md.
// Ported from @scaleflex/asset-picker. Labels are a cross-folder navigation axis;
// they are simple tags (NOT metadata) so they fit within "light".
import type { DamClient } from './dam-client';
import type { Label } from '../types/label.types';
import type { ApiStatusResponse } from '../types/api.types';

interface GetLabelsResponse extends ApiStatusResponse {
  labels: Label[];
}

export async function getLabels(client: DamClient): Promise<Label[]> {
  const res = await client.get<GetLabelsResponse>('/labels');
  return res.labels ?? [];
}

/**
 * Build the Files API query that filters by a label, mirroring asset-picker:
 * `q=labels:{sid}` with the leading "#" stripped from the label's sid.
 * Returns undefined for a label with no usable sid (caller skips the filter).
 */
export function labelFilterQuery(label: Label): string | undefined {
  if (!label.sid) return undefined;
  return `labels:${label.sid.replace(/^#/, '')}`;
}
