// Presentation formatters for asset metadata (size / date / dimensions). Pure,
// dependency-free, and locale-aware — shared so every DAM widget renders the
// same "File info" values. UI-free (returns plain strings); callers do the markup.

/** Human-readable byte size ("—" when unknown, e.g. "1.4 MB", "512 B"). */
export function formatFileSize(bytes?: number | null): string {
  // Guard non-finite/NaN/negative too — `raw.size` flows in un-coerced from the API.
  if (bytes == null || !Number.isFinite(bytes) || bytes < 0) return '—';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
  }
  // Whole bytes; larger units show 1 decimal under 10, none at/above. Precision is
  // decided on the value rounded to 1dp so 9.95 prints "10 KB" (not "10.0 KB").
  const fmt = (v: number, unit: number) => {
    const dp = unit > 0 && Math.round(v * 10) / 10 < 10 ? 1 : 0;
    const str = v.toFixed(dp);
    return { str, rounded: Number(str) };
  };
  const first = fmt(value, i);
  let str = first.str;
  // A value that rounds up to 1024 rolls into the next unit (1024 KB → "1.0 MB").
  if (first.rounded >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
    str = fmt(value, i).str;
  }
  return `${str} ${units[i]}`;
}

/** Short, locale-aware date ("—" when missing; echoes the raw value if unparseable). */
export function formatDate(iso?: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

/** "W × H" pixel dimensions, or "—" when either side is missing. */
export function formatDimensions(width?: number | null, height?: number | null): string {
  return width && height ? `${width} × ${height}` : '—';
}
