import { LitElement, html, css, nothing } from 'lit';
import { property, query } from 'lit/decorators.js';
import { resetStyles } from '../styles/reset';
import { customElement } from '../utils/define-element';
import './sfx-spinner';

/**
 * Shared modal dialog — `confirm` (message + Cancel/OK) or `prompt` (text input).
 * Token-driven (`--sfx-*`), with backdrop + Escape to cancel, Enter to confirm, autofocus,
 * an optional `loading` spinner, an `error` line, and a default slot for custom body content
 * (e.g. a "In /path" hint). Presentational + uncontrolled-open: the host conditionally renders
 * it (presence = open) and reacts to the events; it never closes itself, so a host can keep it
 * open to surface a validation/API error.
 *
 * Events: `sfx-dialog-confirm` (`detail.value` = trimmed input for prompt, else `''`),
 * `sfx-dialog-cancel`, and `sfx-dialog-input` (`detail.value`, on each keystroke in prompt mode).
 */
@customElement('sfx-dialog')
export class SfxDialog extends LitElement {
  static styles = [
    resetStyles,
    css`
      :host {
        display: block;
      }
      .backdrop {
        position: fixed;
        inset: 0;
        z-index: var(--sfx-dialog-z-index, 100);
        background: oklch(0 0 0 / 0.4);
        display: flex;
        align-items: center;
        justify-content: center;
        animation: sfx-dlg-backdrop-in 150ms ease-out;
      }
      .dialog {
        background: var(--sfx-background, oklch(1 0 0));
        border-radius: var(--sfx-radius-lg, 12px);
        padding: 24px 28px 20px;
        max-width: var(--sfx-dialog-max-width, 440px);
        width: 90%;
        box-shadow: 0 16px 48px oklch(0 0 0 / 0.16);
        font-family: var(--sfx-font-family, system-ui, sans-serif);
        animation: sfx-dlg-dialog-in 180ms ease-out;
      }
      @keyframes sfx-dlg-backdrop-in {
        from {
          opacity: 0;
        }
        to {
          opacity: 1;
        }
      }
      @keyframes sfx-dlg-dialog-in {
        from {
          opacity: 0;
          transform: scale(0.96);
        }
        to {
          opacity: 1;
          transform: scale(1);
        }
      }
      @media (prefers-reduced-motion: reduce) {
        .backdrop,
        .dialog {
          animation: none;
        }
      }
      .title {
        font-size: 1rem;
        font-weight: 600;
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        margin-bottom: 6px;
      }
      .message {
        font-size: var(--sfx-font-size-sm, 0.875rem);
        color: var(--sfx-secondary-foreground, oklch(53.03% 0.039 249.89));
        margin-bottom: 16px;
        line-height: 1.5;
      }
      ::slotted(*) {
        margin-bottom: 16px;
      }
      input {
        width: 100%;
        box-sizing: border-box;
        height: 36px;
        padding: 0 12px;
        border: 1px solid var(--sfx-input, oklch(0.871 0.016 241.798));
        border-radius: var(--sfx-radius-sm, 6px);
        font-size: var(--sfx-font-size-sm, 0.875rem);
        font-family: var(--sfx-font-family, system-ui, sans-serif);
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        background: var(--sfx-background, oklch(1 0 0));
        outline: none;
      }
      input:hover {
        border-color: var(--sfx-secondary-foreground-50, oklch(53.03% 0.039 249.89 / 0.5));
      }
      input:focus {
        border-color: var(--sfx-ring, oklch(0.578 0.198 268.129 / 0.7));
        box-shadow: 0 0 0 2px var(--sfx-primary-10, oklch(0.578 0.198 268.129 / 0.1));
      }
      .error {
        font-size: 0.8125rem;
        color: var(--sfx-destructive, oklch(0.577 0.245 27.325));
        margin: 6px 0 0;
        line-height: 1.25rem;
      }
      .actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 16px;
      }
      .btn {
        padding: 8px 20px;
        border-radius: var(--sfx-radius-sm, 6px);
        font-size: var(--sfx-font-size-sm, 0.875rem);
        font-weight: 500;
        cursor: pointer;
        transition: background 100ms;
        font-family: var(--sfx-font-family, system-ui, sans-serif);
        border: 1px solid var(--sfx-border, oklch(92.86% 0.009 247.92));
        background: var(--sfx-background, oklch(1 0 0));
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
      }
      .btn:not(.btn-primary):not(.btn-danger):hover {
        background: var(--sfx-muted, oklch(0.974 0.006 239.819));
      }
      .btn-primary {
        background: var(--sfx-primary, oklch(0.578 0.198 268.129));
        color: var(--sfx-primary-foreground, oklch(1 0 0));
        border-color: var(--sfx-primary, oklch(0.578 0.198 268.129));
      }
      .btn-danger {
        background: var(--sfx-destructive, oklch(0.577 0.245 27.325));
        color: var(--sfx-destructive-foreground, oklch(1 0 0));
        border-color: var(--sfx-destructive, oklch(0.577 0.245 27.325));
      }
      .btn-primary:hover,
      .btn-danger:hover {
        opacity: 0.9;
      }
      .btn:disabled {
        opacity: 0.5;
        cursor: default;
      }
      .loading-content {
        display: flex;
        align-items: center;
        gap: 8px;
      }
    `,
  ];

  /** `confirm` shows a message; `prompt` shows a text input. */
  @property() kind: 'confirm' | 'prompt' = 'confirm';
  @property() heading = '';
  @property() message = '';
  /** Initial input value (prompt). */
  @property() value = '';
  @property() placeholder = '';
  @property() confirmLabel = 'Confirm';
  @property() cancelLabel = 'Cancel';
  @property({ type: Boolean }) danger = false;
  @property({ type: Boolean }) loading = false;
  /** Disable the confirm button (e.g. empty/invalid input) without disabling cancel. */
  @property({ type: Boolean }) confirmDisabled = false;
  @property() error: string | null = null;

  @query('input') private _input?: HTMLInputElement;

  // Connected dialogs, in mount order — Escape only cancels the topmost so a stacked
  // dialog doesn't also dismiss the one beneath it.
  private static _stack: SfxDialog[] = [];

  connectedCallback() {
    super.connectedCallback();
    SfxDialog._stack.push(this);
    document.addEventListener('keydown', this._handleDocKeyDown);
    requestAnimationFrame(() => {
      this._input?.focus();
      this._input?.select();
    });
  }

  disconnectedCallback() {
    document.removeEventListener('keydown', this._handleDocKeyDown);
    SfxDialog._stack = SfxDialog._stack.filter((d) => d !== this);
    super.disconnectedCallback();
  }

  /** Current input text (prompt mode), trimmed. */
  get inputValue(): string {
    return (this._input?.value ?? this.value).trim();
  }

  private _handleDocKeyDown = (e: KeyboardEvent) => {
    // Only the topmost open dialog reacts to Escape.
    if (e.key === 'Escape' && SfxDialog._stack[SfxDialog._stack.length - 1] === this) {
      e.preventDefault();
      this._cancel();
    }
  };

  private _onInput(e: Event) {
    this.dispatchEvent(
      new CustomEvent('sfx-dialog-input', {
        detail: { value: (e.target as HTMLInputElement).value },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private _confirm() {
    if (this.loading || this.confirmDisabled) return;
    this.dispatchEvent(
      new CustomEvent('sfx-dialog-confirm', {
        detail: { value: this.kind === 'prompt' ? this.inputValue : '' },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private _cancel() {
    this.dispatchEvent(new CustomEvent('sfx-dialog-cancel', { bubbles: true, composed: true }));
  }

  private _onBackdrop(e: MouseEvent) {
    if (e.target === e.currentTarget) this._cancel();
  }

  private _onInputKeyDown(e: KeyboardEvent) {
    if (e.key === 'Enter') {
      e.preventDefault();
      this._confirm();
    }
  }

  render() {
    return html`
      <div class="backdrop" @click=${this._onBackdrop}>
        <div class="dialog" role="dialog" aria-modal="true" aria-label=${this.heading}>
          ${this.heading ? html`<div class="title">${this.heading}</div>` : nothing}
          ${this.message && this.kind === 'confirm'
            ? html`<div class="message">${this.message}</div>`
            : nothing}
          <slot></slot>
          ${this.kind === 'prompt'
            ? html`<input
                type="text"
                placeholder=${this.placeholder}
                .value=${this.value}
                ?disabled=${this.loading}
                @input=${this._onInput}
                @keydown=${this._onInputKeyDown}
                aria-label=${this.heading || this.placeholder}
                aria-invalid=${this.error ? 'true' : 'false'}
              />`
            : nothing}
          ${this.error ? html`<div class="error" role="alert">${this.error}</div>` : nothing}
          <div class="actions">
            <button class="btn" @click=${this._cancel}>${this.cancelLabel}</button>
            <button
              class="btn ${this.danger ? 'btn-danger' : 'btn-primary'}"
              @click=${this._confirm}
              ?disabled=${this.loading || this.confirmDisabled}
            >
              ${this.loading
                ? html`<span class="loading-content"
                    ><sfx-spinner .size=${14}></sfx-spinner> ${this.confirmLabel}</span
                  >`
                : this.confirmLabel}
            </button>
          </div>
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-dialog': SfxDialog;
  }
}
